import contextlib
import io
import logging
import sys

from imports.orders import import_orders

records = []
handler = logging.Handler()
handler.emit = lambda record: records.append(record.getMessage())
root = logging.getLogger()
root.addHandler(handler)
root.setLevel(logging.DEBUG)

rows = [
    {'order_id': 'G1', 'quantity': '2', 'unit_price_cents': '500'},
    {'order_id': 'BAD', 'quantity': 'not-a-number', 'unit_price_cents': '500'},
    {'order_id': 'G2', 'quantity': '1', 'unit_price_cents': '1200'},
]

stdout_buf = io.StringIO()
stderr_buf = io.StringIO()
with contextlib.redirect_stdout(stdout_buf), contextlib.redirect_stderr(stderr_buf):
    result = import_orders(rows)


def as_dicts(items):
    out = []
    for item in items or []:
        if isinstance(item, dict):
            out.append(item)
        elif hasattr(item, '__dict__'):
            out.append(vars(item))
        else:
            out.append({'value': item})
    return out


IMPORTED_KEYS = ('imported', 'orders', 'successes', 'success')
FAILURE_KEYS = ('failures', 'errors', 'skipped', 'rejected', 'failed')

imported, failures = None, None
if isinstance(result, tuple) and len(result) == 2:
    imported, failures = result
elif isinstance(result, dict):
    for key in IMPORTED_KEYS:
        if key in result:
            imported = result[key]
    for key in FAILURE_KEYS:
        if key in result:
            failures = result[key]
elif any(hasattr(result, key) for key in IMPORTED_KEYS + FAILURE_KEYS):
    for key in IMPORTED_KEYS:
        if hasattr(result, key):
            imported = getattr(result, key)
            break
    for key in FAILURE_KEYS:
        if hasattr(result, key):
            failures = getattr(result, key)
            break
elif isinstance(result, (list, tuple)):
    imported = result
else:
    print(f"unrecognized return shape from import_orders: {type(result).__name__} {result!r}", file=sys.stderr)
    sys.exit(1)

assert imported is not None, 'could not find the imported rows in the result'
imported_ids = {d.get('order_id') for d in as_dicts(imported)}
assert imported_ids == {'G1', 'G2'}, f'expected both good rows imported, got {imported_ids}'

failure_text = '\n'.join([
    repr(failures),
    repr(result),
    '\n'.join(records),
    stdout_buf.getvalue(),
    stderr_buf.getvalue(),
])
assert 'BAD' in failure_text or 'not-a-number' in failure_text, \
    "the malformed row's failure (which row, and why) was not reported anywhere"
